export const QUESTS=[
{id:'first_light',chapter:1,title:'A place beyond the Curtain',description:'Attune a checkpoint at Jujutsu High. Every sorcerer needs a place to return to.',objectives:[{kind:'checkpoint',region:'school',target:1,label:'Attune a school checkpoint'}],rewards:{wood:3,crystal:2},requires:[]},
{id:'forest_supplies',chapter:1,title:'Supplies for the sanctuary',description:'Harvest three resources in Whispering Shrine. Wood and cursed crystals will keep the lanterns burning.',objectives:[{kind:'harvest',region:'forest',target:3,label:'Harvest forest resources'}],rewards:{wood:4,crystal:3,gem:2},unlocks:['tokyo'],requires:['first_light']},
{id:'lantern_watch',chapter:1,title:'A light against the dark',description:'Upgrade a shrine lantern. Its purification aura restores your squad and slows approaching curses.',objectives:[{kind:'lantern',target:1,label:'Upgrade a purification lantern'}],rewards:{gem:3,herb:2},requires:['forest_supplies']},
{id:'womb_hunt',chapter:1,title:'The cursed womb',description:'A Finger Bearer is gathering cursed energy in the forest. Challenge it with your squad.',region:'forest',boss:'finger',objectives:[{kind:'boss',boss:'finger',region:'forest',target:1,label:'Exorcise the Finger Bearer'}],rewards:{gem:6,herb:2},levelReward:1,requires:['lantern_watch']},
{id:'tokyo_patrol',chapter:2,title:'Trouble in the backstreets',description:'Clear three curses in Tokyo and attune a city checkpoint to secure your route.',objectives:[{kind:'kills',region:'tokyo',target:3,label:'Exorcise Tokyo curses'},{kind:'checkpoint',region:'tokyo',target:1,label:'Attune a Tokyo checkpoint'}],rewards:{gem:5,crystal:3},requires:['womb_hunt']},
{id:'volcano_hunt',chapter:2,title:'Embers in the city',description:'Jogo has turned the backstreets into his hunting ground. Dodge the eruption warnings and extinguish the curse.',region:'tokyo',boss:'jogo',objectives:[{kind:'boss',boss:'jogo',region:'tokyo',target:1,label:'Defeat Jogo'}],rewards:{gem:8,herb:3},unlocks:['shibuya'],levelReward:1,requires:['tokyo_patrol']},
{id:'shibuya_seals',chapter:3,title:'Beneath the Shibuya Curtain',description:'Attune both Shibuya checkpoints before confronting the disaster curses.',objectives:[{kind:'checkpoint',region:'shibuya',target:2,label:'Attune Shibuya checkpoints'}],rewards:{gem:6,crystal:4},requires:['volcano_hunt']},
{id:'roots_hunt',chapter:3,title:'Roots of the disaster',description:'Hanami waits in Shibuya. Keep moving when the roots mark the ground beneath your squad.',region:'shibuya',boss:'hanami',objectives:[{kind:'boss',boss:'hanami',region:'shibuya',target:1,label:'Defeat Hanami'}],rewards:{gem:10,herb:3},requires:['shibuya_seals']},
{id:'soul_hunt',chapter:3,title:'The shape of a soul',description:'Mahito stalks the underground approaches. Read his lunges and fight together.',region:'shibuya',boss:'mahito',objectives:[{kind:'boss',boss:'mahito',region:'shibuya',target:1,label:'Defeat Mahito'}],rewards:{gem:12,herb:3},unlocks:['domain'],levelReward:1,requires:['roots_hunt']},
{id:'king_hunt',chapter:4,title:'The King of Curses',description:'Enter the cursed domain and face Ryomen Sukuna. Save your ultimate for the opening after his slash.',region:'domain',boss:'sukuna',objectives:[{kind:'boss',boss:'sukuna',region:'domain',target:1,label:'Defeat Ryomen Sukuna'}],rewards:{gem:20,herb:5},levelReward:2,requires:['soul_hunt']}
];
export function ensureQuests(s){s.quests??={version:1,claimed:[],tracked:'first_light',activeHunt:null,stats:{harvests:{forest:s.harvests||0},bosses:{}}};s.quests.claimed??=[];s.quests.stats??={};s.quests.stats.harvests??={};s.quests.stats.bosses??={};return s.quests;}
export function objectiveValue(s,o){const q=ensureQuests(s);if(o.kind==='checkpoint')return s.discovered.filter(id=>id.startsWith(o.region+'-')).length;if(o.kind==='harvest')return q.stats.harvests[o.region]||0;if(o.kind==='lantern')return s.objects.reduce((n,x)=>n+(x.upgrade||0),0);if(o.kind==='kills')return s.regionKills[o.region]||0;if(o.kind==='boss')return q.stats.bosses[`${o.region}:${o.boss}`]||0;return 0;}
export function questAvailable(s,q){return q.requires.every(id=>ensureQuests(s).claimed.includes(id));}
export function questReady(s,q){return questAvailable(s,q)&&q.objectives.every(o=>objectiveValue(s,o)>=o.target);}
export function activeQuest(s){const state=ensureQuests(s);return QUESTS.find(q=>q.id===state.tracked&&!state.claimed.includes(q.id)&&questAvailable(s,q))||QUESTS.find(q=>!state.claimed.includes(q.id)&&questAvailable(s,q))||null;}
export function recordQuestEvent(s,kind,data={}){if(s.mode!=='survival')return;const q=ensureQuests(s);if(kind==='harvest')q.stats.harvests[data.region]=(q.stats.harvests[data.region]||0)+1;if(kind==='boss'){const key=`${data.region}:${data.boss}`;q.stats.bosses[key]=(q.stats.bosses[key]||0)+1;q.activeHunt=null;}}
export function claimQuest(s,id){if(s.mode!=='survival')return null;const state=ensureQuests(s),q=QUESTS.find(q=>q.id===id);if(!q||state.claimed.includes(id)||!questReady(s,q))return null;state.claimed.push(id);for(const [key,n]of Object.entries(q.rewards))s.inventory[key]+=n;for(const region of q.unlocks||[])if(!s.unlocked.includes(region))s.unlocked.push(region);state.tracked=QUESTS.find(next=>!state.claimed.includes(next.id)&&questAvailable(s,next))?.id||null;return q;}
export function questSummary(s){const q=activeQuest(s);if(!q)return {title:'The valley is yours',description:'All ten campaign quests are complete. Explore, train, and challenge more curses.',progress:1};const current=q.objectives.reduce((a,o)=>a+Math.min(objectiveValue(s,o),o.target),0),total=q.objectives.reduce((a,o)=>a+o.target,0);return {title:q.title,description:q.description,progress:current/total,current,total,ready:questReady(s,q),quest:q};}
